import{V as e,et as t,gt as n,tt as r}from"./chunks/framework.B_R1PD8Q.js";var i=JSON.parse(`{"title":"📠 Change Log","description":"","frontmatter":{},"headers":[],"relativePath":"en-US/guide/changelog.md","filePath":"en-US/guide/changelog.md","lastUpdated":1785522159000}`),a={name:`en-US/guide/changelog.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="📠-change-log" tabindex="-1">📠 Change Log <a class="header-anchor" href="#📠-change-log" aria-label="Permalink to “📠 Change Log”">​</a></h1><h2 id="_10-0-1" tabindex="-1">10.0.1 <a class="header-anchor" href="#_10-0-1" aria-label="Permalink to “10.0.1”">​</a></h2><p><code>2026-08-01</code></p><ul><li>💄 Improve mobile inertial scrolling for smoother and more consistent animations.</li><li>💄 Improve mobile touch handling to prevent page scrolling and browser navigation gestures while dragging the chart.</li><li>💄 Improve the state and lifecycle management of area chart ripple animations.</li><li>💄 Improve Canvas rendering scheduling, resizing, and device pixel ratio handling.</li><li>🐞 Fix an incorrect formula in the built-in <code>PVT</code> indicator.</li><li>🐞 Fix <code>rgbToHex</code> incorrectly using the red channel value when converting the green and blue channels.</li><li>🐞 Fix regular expression errors in <code>hsla</code> color validation and transparent color detection.</li><li>🐞 Fix declaration file builds failing in some environments.</li></ul><h2 id="_10-0-0" tabindex="-1">10.0.0 <a class="header-anchor" href="#_10-0-0" aria-label="Permalink to “10.0.0”">​</a></h2><p><code>2026-07-11</code></p><p>The current 10.x release is a major upgrade from 9.x. It reorganizes data loading, layout, axes, indicators, overlays, formatting, and style configuration.</p><h3 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to “New Features”">​</a></h3><ul><li>🆕 Support multiple y-axes. A pane can contain multiple y-axes, and indicators can bind to a specific axis with <code>indicator.yAxisId</code>.</li><li>🆕 Add instance methods <code>createYAxis(yAxis)</code>, <code>removeYAxis(filter)</code>, <code>getYAxes(filter)</code>, <code>overrideYAxis(options)</code>, and <code>overrideXAxis(options)</code>.</li><li>🆕 Support custom hotkeys, with the new <code>hotkey</code> option and APIs such as <code>setHotkey</code>, <code>getHotkey</code>, <code>registerHotkey</code>, and <code>getSupportedHotkeys</code>.</li><li>🆕 Add continuous drawing mode for overlays, and add the built-in <code>brush</code> overlay.</li><li>🆕 Support custom thousands separators and decimal-zero folding.</li><li>🆕 Support zoom anchors with the <code>zoomAnchor</code> option and <code>setZoomAnchor(anchor)</code> / <code>getZoomAnchor()</code>.</li><li>🆕 Add <code>setDataLoader(loader)</code> for historical data, realtime data, and backward loading.</li><li>🆕 Add <code>setSymbol(symbol)</code>, <code>getSymbol()</code>, <code>setPeriod(period)</code>, and <code>getPeriod()</code>.</li><li>🆕 Support future time on the x-axis.</li><li>🆕 Support y-axis dragging on mobile.</li><li>🆕 Support multiple indicators with the same name in the same pane.</li><li>🆕 Rewrite the axis module. Custom y-axes can define ranges and ticks.</li><li>🆕 Add the <code>text</code> figure type for indicators.</li><li>🆕 Add <code>getIndicators(filter)</code> and <code>getOverlays(filter)</code>.</li><li>🆕 Add style options including <code>candle.priceMark.last.extendTexts</code>, <code>candle.tooltip.title</code>, <code>candle.tooltip.legend</code>, <code>indicator.tooltip.title</code>, <code>indicator.tooltip.legend</code>, <code>crosshair.horizontal.features</code>, <code>candle.bar.compareRule</code>, <code>indicator.ohlc.compareRule</code>, and <code>candle.priceMark.last.compareRule</code>.</li><li>🆕 Add <code>onIndicatorTooltipFeatureClick</code> and <code>onCrosshairFeatureClick</code> action types.</li></ul><h3 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to “Changes”">​</a></h3><ul><li>👉 In <code>init(ds, options)</code>, <code>options.layout</code> is now a default layout configuration object: <ul><li><code>layout.barSpaceLimit</code> configures bar-space limits.</li><li><code>layout.pane</code> configures default pane options.</li><li><code>layout.yAxis</code> configures default y-axis options.</li></ul></li><li>👉 <code>createIndicator(indicator, options?)</code> is adjusted to <code>createIndicator(indicator, isStack?)</code>. Use <code>indicator.paneId</code> for pane placement and <code>indicator.yAxisId</code> for y-axis binding.</li><li>👉 <code>setPaneOptions(options)</code> only configures pane options. Use <code>overrideXAxis(options)</code>, <code>overrideYAxis(options)</code>, or the multi-y-axis APIs for axis configuration.</li><li>👉 Add <code>yAxisId</code> to the <code>filter</code> parameter of <code>convertToPixel(value, filter?)</code> and <code>convertFromPixel(coordinate, filter?)</code>.</li><li>👉 <code>options.customApi</code> is renamed to <code>options.formatter</code>; <code>setCustomApi</code> is renamed to <code>setFormatter</code>; <code>getCustomApi</code> is renamed to <code>getFormatter</code>.</li><li>👉 <code>formatDate(dateTimeFormat, timestamp, format, type)</code> is changed to <code>formatDate({ dateTimeFormat, timestamp, template, type })</code>.</li><li>👉 <code>options.thousandsSeparator</code> is changed to an object <code>{ sign, format }</code>.</li><li>👉 <code>options.decimalFoldThreshold</code> is changed to <code>options.decimalFold</code>.</li><li>👉 <code>getBarSpace()</code> now returns an object.</li><li>👉 <code>createIndicator</code> now returns the indicator id.</li><li>👉 Custom indicator <code>calc</code> now returns an object keyed by timestamp instead of an array.</li><li>👉 In custom indicator <code>createTooltipDataSource</code>, <code>values</code> is renamed to <code>legends</code>, and <code>icons</code> is renamed to <code>features</code>.</li><li>👉 <code>candle.tooltip.icons</code> is renamed to <code>candle.tooltip.features</code>; <code>indicator.tooltip.icons</code> is renamed to <code>indicator.tooltip.features</code>.</li><li>👉 Adjust the calculation logic of the built-in <code>RSI</code> indicator.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to “Removed”">​</a></h3><ul><li>🗑 Remove <code>utils.drawArc</code>, <code>utils.drawCircle</code>, <code>utils.drawLine</code>, <code>utils.drawPolygon</code>, <code>utils.drawRect</code>, <code>utils.drawText</code>, and <code>utils.drawRectText</code>. Use <code>getFigureClass(name)</code> instead.</li><li>🗑 Remove <code>setPriceVolumePrecision(pricePrecision, volumePrecision)</code>. Use precision fields in <code>setSymbol(symbol)</code>.</li><li>🗑 Remove <code>setLoadMoreData</code>, <code>applyNewData</code>, <code>applyMoreData</code>, <code>updateData</code>, <code>setLoadDataCallback</code>, and <code>loadMore</code>. Use <code>setDataLoader(loader)</code>.</li><li>🗑 Remove <code>clearData()</code>. Use <code>resetData()</code> to reload data.</li><li>🗑 Remove <code>getIndicatorByPaneId(paneId, name)</code>. Use <code>getIndicators(filter)</code>.</li><li>🗑 Remove <code>getOverlayById(id)</code>. Use <code>getOverlays(filter)</code>.</li><li>🗑 Remove <code>onTooltipIconClick</code> from <code>subscribeAction</code> and <code>unsubscribeAction</code>. Use <code>onCandleTooltipFeatureClick</code> and <code>onIndicatorTooltipFeatureClick</code>.</li><li>🗑 Remove style options <code>yAxis.position</code>, <code>yAxis.type</code>, and <code>yAxis.inside</code>. Use default <code>layout.yAxis</code> options or instance y-axis APIs.</li><li>🗑 Remove style options <code>candle.tooltip.defaultValue</code>, <code>candle.tooltip.custom</code>, <code>candle.tooltip.text</code>, <code>indicator.tooltip.showName</code>, <code>indicator.tooltip.showParams</code>, <code>indicator.tooltip.defaultValue</code>, <code>indicator.tooltip.text</code>, and <code>overlay.rectText</code>.</li><li>🗑 Remove the built-in <code>rectText</code> figure. Use <code>text</code> instead.</li></ul><h3 id="fixes-and-optimizations" tabindex="-1">Fixes and Optimizations <a class="header-anchor" href="#fixes-and-optimizations" aria-label="Permalink to “Fixes and Optimizations”">​</a></h3><ul><li>🐞 Fix scrolling when an event falls on a locked overlay.</li><li>🐞 Fix overlays that are force-ended during drawing not being restorable through <code>createOverlay</code>.</li><li>🐞 Fix overlay drawing response in weak magnet mode.</li><li>🐞 Fix data callbacks being triggered repeatedly when loading data backward.</li><li>🐞 Fix cases where <code>resize</code> may not take effect.</li><li>🐞 Fix the parameter type of <code>setZoomAnchor</code>.</li><li>💄 Automatically observe container size changes and call <code>resize()</code>.</li><li>💄 Optimize ignored figure events in overlay templates so event names align with overlay events.</li><li>💄 Optimize indicator calculation tasks.</li><li>💄 Optimize mobile scrolling events.</li><li>💄 Change the build tool from Rollup to Vite and add <code>type-check</code>.</li></ul><h2 id="_9-x" tabindex="-1">9.x <a class="header-anchor" href="#_9-x" aria-label="Permalink to “9.x”">​</a></h2><p>Go to <a href="https://v9.klinecharts.com" target="_blank" rel="noreferrer">https://v9.klinecharts.com</a> to check the change log for 9.x.</p><h2 id="_8-x" tabindex="-1">8.x <a class="header-anchor" href="#_8-x" aria-label="Permalink to “8.x”">​</a></h2><p>Go to <a href="https://v8.klinecharts.com" target="_blank" rel="noreferrer">https://v8.klinecharts.com</a> to check the change log for 8.x.</p><h2 id="_7-x" tabindex="-1">7.x <a class="header-anchor" href="#_7-x" aria-label="Permalink to “7.x”">​</a></h2><p>Go to <a href="https://github.com/liihuu/KLineChart/blob/v7.5.0/docs/en/changelog.md" target="_blank" rel="noreferrer">Github</a> to check the change log for 7.x.</p><h2 id="_6-x" tabindex="-1">6.x <a class="header-anchor" href="#_6-x" aria-label="Permalink to “6.x”">​</a></h2><p>Go to <a href="https://github.com/liihuu/KLineChart/blob/v6.1.0/docs/en/CHANGELOG.md" target="_blank" rel="noreferrer">Github</a> to check the change log for 6.x.</p><h2 id="_5-x" tabindex="-1">5.x <a class="header-anchor" href="#_5-x" aria-label="Permalink to “5.x”">​</a></h2><p>Go to <a href="https://github.com/liihuu/KLineChart/releases/tag/v5.0.0" target="_blank" rel="noreferrer">Github</a> to view the 5.x release notes.</p><h2 id="_4-x" tabindex="-1">4.x <a class="header-anchor" href="#_4-x" aria-label="Permalink to “4.x”">​</a></h2><p>Go to <a href="https://github.com/liihuu/KLineChart/releases/tag/v4.0.0" target="_blank" rel="noreferrer">Github</a> to view the 4.x release notes.</p>`,27)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};